/* ============================ i18n 框架 ============================
   多语言基础设施。设计目标：
   ① 零依赖、零构建 —— 静态文件直接引，与项目「不用打包器」的现状一致
   ② 切换语言**不刷新页面** —— 已渲染的 DOM 也要跟着变
   ③ 缺词**有可见降级** —— 显示中文原文并在控制台警告，不显示空白
   ④ 支持 {0} {1} 占位符，避免为拼接句子写死一堆变体
   ⑤ 持久化到 localStorage，下次打开记住选择

   用法：
     t('nav.dash')                    → '系统概览' / 'System Overview'
     t('kv.version')                  → '版本' / 'Version'
     t('upd.count', [n])              → '共 12 条' / '12 items'
     t('unknown.key')                 → 'unknown.key'（并 warn）

   ⚠️ 为什么不用 data-i18n 属性遍历 DOM：
   那样只能替换静态属性，**innerHTML 里拼出来的文案管不到** ——
   而本项目大量文案是模板字符串里拼的。
   所以这里用「t() 显式调用」，由代码来决定哪里需要翻译。
   ------------------------------------------------------------------------ */
