      '每个包里都带一份清单（导出于哪台机器、什么版本、每个文件的校验值）， 还原前会先校验，文件对不上就拒绝写入': { zh: '每个包里都带一份清单（导出于哪台机器、什么版本、每个文件的校验值）， 还原前会先校验，文件对不上就拒绝写入', en: 'Every package carries a manifest (which machine it was exported from, which version, and the checksum of every file). It is verified before the restore, and the restore is refused if any file does not match' },
      '每台设备一套独立密钥。删除某台设备等于吊销它的访问权限': { zh: '每台设备一套独立密钥。删除某台设备等于吊销它的访问权限', en: 'Each device has its own set of keys. Deleting a device is equivalent to revoking its access' },
