      '每条规则下面都写了「为什么是这个数」。阈值太松会漏报， 太紧会变成每天几十条推送的噪音，最后你直接把通知静音': { zh: '每条规则下面都写了「为什么是这个数」。阈值太松会漏报， 太紧会变成每天几十条推送的噪音，最后你直接把通知静音', en: 'Each rule explains "why this number" below it. A threshold that is too loose misses events; one that is too tight turns into the noise of dozens of pushes a day, until you simply mute the notification' },
