      '前三段必须和本机 LAN 地址一致，最后一段落在 2–254 之间。': { zh: '前三段必须和本机 LAN 地址一致，最后一段落在 2–254 之间。', en: 'The first three octets must match this host’s LAN address; the last must fall between 2 and 254.' },
      '起始–结束这段不要包含本机自己的地址（否则会和本机抢 IP）。': { zh: '起始–结束这段不要包含本机自己的地址（否则会和本机抢 IP）。', en: 'The start-to-end range must not contain this host’s own address, or it will clash with the host.' },
