      '这几种已验证可用，覆盖了绝大多数家庭宽带与 NAS 的需求。': { zh: '这几种已验证可用，覆盖了绝大多数家庭宽带与 NAS 的需求。', en: 'These have been verified to work and cover the needs of most home broadband and NAS setups.' },
