      '这台机器已经能把内网接到外网了。下面的步骤可以随时回来复查或调整。': { zh: '这台机器已经能把内网接到外网了。下面的步骤可以随时回来复查或调整。', en: 'This machine can already connect the LAN to the internet. You can come back to review or adjust the steps any time.' },
