        '网卡备注与角色绑定': { 'en': 'NIC notes and role bindings' },
        '网卡与桥接、LAN / WAN 口参数': { 'en': 'NICs and bridges, LAN / WAN port parameters' },
        'DHCP 与 DNS（drouter.conf）': { 'en': 'DHCP and DNS (drouter.conf)' },
        'IPv6 地址池、RA 通告、DHCPv6 前缀委派': { 'en': 'IPv6 address pools, RA announcements, DHCPv6 prefix delegation' },
        'IPv4 / IPv6 防火墙规则集（nftables）': { 'en': 'IPv4 / IPv6 firewall rulesets (nftables)' },
