      /* 页面级整段说明（后端下发中文）—— 按原文当键，bt4 查英文 */
      /* 页面级整段说明（后端下发中文）—— key 逐字节等于真机原文 */
      'PAGE_NOTES': {
        '当前内核里没有 drouter 的防火墙规则（nft 规则集为空），还没有任何包经过本机的防火墙链，所以这里不会有记录。请到「防火墙 IPv4 / IPv6」页面点一次「应用」，规则载入后即可开始记录。':
          { 'd': 'There are no drouter firewall rules in the kernel yet (the nft ruleset is empty), so no packet has traversed the firewall chain and there is nothing to show. Open the "Firewall IPv4 / IPv6" page and click "Apply" once — recording starts as soon as the rules are loaded.' },
        '防火墙日志开关当前为关闭：规则里不会生成 log 语句，因此这里不会有新记录。':
          { 'd': 'The firewall logging switch is currently off: the rules contain no log statements, so no new records will appear here.' },
        '所有接口统一返回 {"ok":..,"msg_cn":..,"data":..}；失败时 ok=false。除 /api/health、/api/login 外均需 X-Token 头。':
          { 'd': 'Every endpoint returns {"ok":..,"msg_cn":..,"data":..}; on failure ok=false. Everything except /api/health and /api/login requires the X-Token header.' },
        '按 Diffserv 分为三档：语音（CS7/CS6/EF/VA，占 25% 带宽份额，Codel 间隔缩短）、尽力（普通流量，占满带宽）、批量（CS1/LE，低优先级，只分到 6.25% 带宽份额，用于下载 / BT / 视频等大流量）。':
          { 'd': 'Three tiers by Diffserv: voice (CS7/CS6/EF/VA, 25% of bandwidth, shorter Codel intervals), best-effort (normal traffic, full bandwidth) and bulk (CS1/LE, lowest priority, 6.25% of bandwidth).' },
        '时间规则按北京时间（UTC+8）换算后写入内核；跨零点的时间段会自动拆成两段。应用识别依赖 DPI 库，限速动作依赖 QoS 模块。':
          { 'd': 'Time rules are converted to Beijing time (UTC+8) before being written into the kernel; a period crossing midnight is split into two. App identification relies on the DPI database, and rate-limit actions rely on the QoS module.' },
        '外接 U 盘 / 移动硬盘 / Type-C 与雷电硬盘盒会显示在下方。「连接方式」显示的是总线类型（USB / 雷电 / NVMe / SATA）；Type-C 是插头形态，电气上仍归 USB 或雷电，因此按总线展示更准确。':
          { 'd': 'External USB drives, portable disks and Thunderbolt enclosures are listed below.' },
        '真正的 Wi-Fi、VLAN、PoE 配置都在 OpenSOHO 自己的控制台里做 —— 这里只负责把它装好、管住、把入口给你。AP 侧需要在 OpenWRT 上装 openwisp-config 并填入下面的共享密钥来注册。':
          { 'd': 'The actual Wi-Fi, VLAN and PoE configuration is done in OpenSOHO\\u2019s own console \\u2014 this page only installs it, keeps it running and gives you the entry point.' },
        'SMB 面向 Windows / macOS / Linux 全平台，兼容性最好；NFS 更适合 Linux 之间互传，性能更高但 Windows 需要额外客户端。两者可以同时开启，共享同一个目录。':
          { 'd': 'SMB covers Windows, macOS and Linux with the best compatibility; NFS suits transfers between Linux machines and performs better, but Windows needs an extra client. Both can be enabled at once and share the same directory.' },
        'Docker 面板支持容器/镜像/网络/卷的日常运维，以及 Compose 项目管理。「命令转换」可以把任意 docker run 命令转成 docker-compose.yml。':
          { 'd': 'This panel handles day-to-day container, image, network and volume work plus Compose project management. The command converter turns any docker run command into docker-compose.yml.' },
        '不使用任何代理。海外网络或已自建代理时选这个。':
          { 'd': 'No proxy at all. Pick this when you are outside China or already run your own proxy.' },
        '老牌公共加速，稳定性一般，偶尔限流。':
          { 'd': 'A long-standing public accelerator: fairly stable but occasionally rate-limited.' },
        '备用加速，支持 release 文件与 raw 文件。':
          { 'd': 'A backup accelerator supporting both release files and raw files.' },
        'Debian 13 仓库直接装，无需编译。nDPI 版本可能略旧，但够家用。':
          { 'd': 'Install straight from the Debian 13 repositories, no compiling. The nDPI version may be slightly older but is fine for home use.' },
      },
