          d: { zh: "把内网设备的私有地址改写成路由器自己的 WAN 地址再发出去。家用宽带通常只给一个公网 IP，内网几十台设备全靠它共用一个出口。", en: "Rewrites the private addresses of LAN devices to the router’s own WAN address on the way out. Home broadband usually hands out a single public IP while the LAN has dozens, so this is what makes sharing work." },
