      copyCsr:  { zh: '复制 CSR', en: 'Copy CSR' },
      copied:   { zh: '已复制', en: 'Copied' },
      copyFail: { zh: '复制失败', en: 'Copy failed' },
      /* SSL/TLS 体检 */
      testTitle:{ zh: 'SSL / TLS 体检', en: 'SSL / TLS Check-up' },
      testDesc: { zh: '对任意主机的任意端口做一次真实握手，看协议版本、加密套件、证书链和校验结论。默认测本机管理后台；也可以测局域网里其它设备、或者外网站点。',
                  en: 'Perform a real handshake against any host and port to inspect the protocol version, cipher suite, certificate chain and verification result. It defaults to this router\'s own console, but you can also test other devices on the LAN or external sites.' },
