      lastDeploy:{ zh: '上次部署（{0}）：{1}',
                   en: 'Last deployment ({0}): {1}' },
      buildWarn:{ zh: '当前处于构建保护模式：部署只会写盘，不会重启 Web 服务。',
                  en: 'Build protection mode is on: deploying only writes to disk and does not restart the web service.' },
      idxBroken:{ zh: '证书库索引文件损坏，列表可能不完整。新建证书会重建它。',
                  en: 'The certificate store index file is corrupted, so the list may be incomplete. Creating a new certificate will rebuild it.' },
      noCert:   { zh: '管理后台现在没有可用的证书：',
                  en: 'The admin console has no usable certificate right now: ' },
