      /* 到期标签（caDaysTag） */
      unknown:  { zh: '未知', en: 'Unknown' },
      expiredDays:{ zh: '已过期 {0} 天', en: 'Expired {0} days ago' },
      daysLeft: { zh: '剩 {0} 天', en: '{0} days left' },
      /* 列表 */
      libEmpty: { zh: '证书库是空的。先在下面「① 创建自己的 CA」建一张。',
                  en: 'The certificate store is empty. Create one under "① Create your own CA" below.' },
      thName:   { zh: '名称', en: 'Name' },
