      restoreAsk:{ zh: '重新生成一张默认自签证书并立即部署？\n\n'
                      + '它会带上本机所有 IP 与 localhost，有效期十年。Web 服务会重启，你需要重新登录。',
                  en: 'Generate a fresh default self-signed certificate and deploy it now?\n\n'
                     + 'It will cover all local IPs and localhost, and is valid for ten years. The web service will restart and you will have to sign in again.' },
      restarting:{ zh: 'Web 服务正在重启，10 秒后自动刷新（需要重新登录一次）',
                   en: 'The web service is restarting; the page refreshes automatically in 10 seconds (you will have to sign in again)' },
      /* 表单标签（三处共用） */
      cnLabel:  { zh: '证书主体 CN', en: 'Certificate subject CN' },
      nameLabel:{ zh: '名称（显示用）', en: 'Name (display only)' },
      namePh:   { zh: '家里的根证书', en: 'Home root certificate' },
      step1Go:  { zh: '创建 CA', en: 'Create CA' },
      daysLabel:{ zh: '有效期（天）', en: 'Validity (days)' },
      keyLabel: { zh: '私钥算法', en: 'Private key algorithm' },
      portLabel:{ zh: '端口', en: 'Port' },
      dnsCnLabel:{ zh: '域名 CN', en: 'Domain CN' },
